function getRegionLabelCenter(id) {
    return regionLabelCenters[id] || regionLabelCenters._default;
}

function generateMapSVG(svg, interactive) {
    if (!svg) return;
    const containerId = svg.id;

    let pathsHTML = '';

    pathsHTML += `
        <path d="M 175,100 L 180,250 L 190,360 L 175,440" stroke="#dc2626" stroke-width="3" stroke-dasharray="4,4" fill="none" opacity="0.8" />
    `;

    myanmarData.forEach(region => {
        const isActive = selectedRegionId === region.id;
        const classes = ['myanmar-map-path'];
        if (isActive) classes.push('active');
        if (!interactive) classes.push('static');

        const events = interactive
            ? ` onmouseover="handleMapHover(event, '${region.name}')" onmouseout="handleMapLeave()" onclick="selectRegion('${region.id}')"`
            : '';

        pathsHTML += `
            <path id="${containerId}-${region.id}"
                  data-id="${region.id}"
                  data-name="${region.name}"
                  class="${classes.join(' ')}"
                  d="${region.path}"${events}>
            </path>
        `;
    });

    myanmarData.forEach(region => {
        const labelCoords = getRegionLabelCenter(region.id);
        pathsHTML += `
            <text x="${labelCoords.x}" y="${labelCoords.y}" class="map-label" text-anchor="middle">${region.name}</text>
        `;
    });

    svg.innerHTML = pathsHTML;
}

function handleMapHover(e, name) {
    const tooltip = document.getElementById('map-tooltip');
    if (!tooltip) return;
    tooltip.style.display = 'block';
    tooltip.innerHTML = `<i class="fa-solid fa-location-dot text-red-500 mr-1.5"></i><strong>${name} Region</strong>`;
    tooltip.style.left = (e.pageX + 15) + 'px';
    tooltip.style.top = (e.pageY - 25) + 'px';
}

function handleMapLeave() {
    const tooltip = document.getElementById('map-tooltip');
    if (tooltip) tooltip.style.display = 'none';
}

function getRiskStyle(level) {
    switch ((level || '').toUpperCase()) {
        case 'VERY HIGH': return { cls: 'risk-very-high', label: 'VERY HIGH RISK' };
        case 'HIGH':      return { cls: 'risk-high',      label: 'HIGH RISK'      };
        case 'MODERATE':  return { cls: 'risk-moderate',  label: 'MODERATE RISK'  };
        case 'LOW':       return { cls: 'risk-low',       label: 'LOW RISK'       };
        default:          return { cls: 'risk-moderate',  label: level + ' RISK'  };
    }
}

function setText(id, text) {
    const el = document.getElementById(id);
    if (el) el.innerText = text;
}

function selectRegion(id) {
    selectedRegionId = id;
    const region = myanmarData.find(r => r.id === id);
    if (!region) return;

    document.querySelectorAll('svg.myanmar-svg').forEach(svg => {
        if (svg.dataset.interactive !== 'true') return;
        svg.querySelectorAll('.myanmar-map-path').forEach(p => {
            if (p.getAttribute('data-id') === id) {
                p.classList.add('active');
            } else {
                p.classList.remove('active');
            }
        });
    });

    setText('risk-region-name', region.name + " State/Region");
    setText('risk-fault-name',  region.fault);
    setText('risk-mag',         region.mag + " Mw");
    setText('risk-pop',         region.pop);
    setText('risk-vuln',        region.vuln);
    setText('risk-meter-label', region.zone);
    setText('risk-desc',        regionDescriptions[region.id] ||
                                (region.name + " — see fault zone and risk level above."));

    const badge = document.getElementById('risk-level-badge');
    if (badge) {
        const style = getRiskStyle(region.level);
        badge.className = 'risk-pill ' + style.cls;
        const txt = document.getElementById('risk-level-text');
        if (txt) txt.innerText = style.label;
    }
    const meter = document.getElementById('risk-meter-indicator');
    if (meter) meter.style.left = region.meterPos + '%';

    setText('db-selected-title', region.name + " Region");
    setText('kpi-need',    region.need);
    setText('kpi-damaged', region.damaged);
    setText('kpi-pop',     region.pop);
    setText('kpi-orgs',    region.orgs);
}

function resetRegionFilter() {
    selectedRegionId = null;
    document.querySelectorAll('.myanmar-map-path').forEach(p => p.classList.remove('active'));

    setText('db-selected-title', "All Myanmar (National)");
    setText('kpi-need',    "921K");
    setText('kpi-damaged', "1,450");
    setText('kpi-pop',     "54.2M");
    setText('kpi-orgs',    "56");
}

function renderMMITable() {
    const tbody = document.getElementById('db-table-body');
    if (!tbody) return;

    tbody.innerHTML = mmiData.map(row => `
        <tr class="hover:bg-slate-50 transition">
            <td class="py-2.5 px-3 font-semibold text-slate-800">${row.intensity}</td>
            <td class="py-2.5 px-3">${row.mmi}</td>
            <td class="py-2.5 px-3 font-bold text-red-600">${row.buildings}</td>
            <td class="py-2.5 px-3">
                <span class="px-2 py-0.5 text-[10px] font-bold rounded bg-red-100 text-red-700">${row.level}</span>
            </td>
        </tr>
    `).join('');
}

function initContactFormValidation() {
    const form = document.getElementById('contact-form');
    if (!form) return;

    function formatPhone(raw) {
        const digits = (raw || '').replace(/\D/g, '').slice(0, 11);
        return digits;
    }

    const fields = [
        {
            input: document.getElementById('contact-name'),
            error: document.getElementById('contact-name-error'),
            validate: (v) => {
                const name = v.trim();
                if (name.length === 0) return 'Name is required.';
                if (name.length < 2)   return 'Please enter your name (at least 2 characters).';
                return '';
            }
        },
        {
            input: document.getElementById('contact-phone'),
            error: document.getElementById('contact-phone-error'),
            validate: (v) => {
                const digits = (v || '').replace(/\D/g, '');
                if (digits.length === 0) {
                    return 'Phone number is required.';
                }
                if (!digits.startsWith('09')) {
                    return 'Phone number must start with 09.';
                }
                if (digits.length !== 11) {
                    return 'Phone number must be exactly 11 digits (including the leading 09). ' +
                           'You entered ' + digits.length + ' digit' + (digits.length === 1 ? '' : 's') + '.';
                }
                return '';
            }
        },
        {
            input: document.getElementById('contact-email'),
            error: document.getElementById('contact-email-error'),
            validate: (v) => {
                const email = v.trim();
                if (email.length === 0) {
                    return 'Email is required.';
                }
                if (!/^[a-zA-Z0-9._%+\-]+@gmail\.com$/.test(email)) {
                    return 'Please enter a valid Gmail address, e.g. name@gmail.com.';
                }
                return '';
            }
        },
        {
            input: document.getElementById('contact-message'),
            error: document.getElementById('contact-message-error'),
            validate: (v) => {
                const msg = v.trim();
                if (msg.length === 0) {
                    return 'Message is required.';
                }
                if (msg.length < 30) {
                    return 'Please write a message of at least 30 characters ' +
                           '(you currently have ' + msg.length + ').';
                }
                return '';
            }
        }
    ];

    const successBox = document.getElementById('form-success');
    const submitBtn  = document.getElementById('contact-submit');

    function runValidation(field) {
        const message = field.validate(field.input.value);
        if (message) {
            field.error.textContent = message;
            field.error.classList.remove('hidden');
            field.input.classList.add('border-red-500');
            field.input.setAttribute('aria-invalid', 'true');
        } else {
            field.error.textContent = '';
            field.error.classList.add('hidden');
            field.input.classList.remove('border-red-500');
            field.input.removeAttribute('aria-invalid');
        }
        return !message;
    }

    function hideSuccess() {
        if (successBox && !successBox.classList.contains('hidden')) {
            successBox.classList.add('hidden');
            successBox.classList.remove('flex');
        }
    }

    fields.forEach(field => {
        field.input.addEventListener('input', () => {
            hideSuccess();
            if (field.input.id === 'contact-phone') {
                const cleaned = formatPhone(field.input.value);
                if (cleaned !== field.input.value) field.input.value = cleaned;
            }
            if (!field.error.classList.contains('hidden')) runValidation(field);
        });
        field.input.addEventListener('blur', () => {
            if (field.input.value.trim() !== '') runValidation(field);
        });
    });

    form.addEventListener('submit', (event) => {
        event.preventDefault(); // no backend — validate and confirm locally

        hideSuccess();

        let firstInvalid = null;
        fields.forEach(field => {
            const ok = runValidation(field);
            if (!ok && !firstInvalid) firstInvalid = field.input;
        });

        if (firstInvalid) {
            firstInvalid.focus();
            return;
        }

        if (submitBtn) {
            submitBtn.disabled = true;
            submitBtn.classList.add('opacity-70', 'cursor-not-allowed');
            const label = submitBtn.querySelector('span');
            const original = label ? label.textContent : 'Send Message';
            if (label) label.textContent = 'Sending...';

            setTimeout(() => {
                if (label) label.textContent = original;
                submitBtn.disabled = false;
                submitBtn.classList.remove('opacity-70', 'cursor-not-allowed');
                form.reset();
                if (successBox) {
                    successBox.classList.remove('hidden');
                    successBox.classList.add('flex');
                }
            }, 900);
        } else {
            form.reset();
            if (successBox) {
                successBox.classList.remove('hidden');
                successBox.classList.add('flex');
            }
        }
    });
}

function initPage() {
    document.querySelectorAll('svg.myanmar-svg').forEach(svg => {
        const interactive = svg.dataset.interactive === 'true';
        generateMapSVG(svg, interactive);
    });
    renderMMITable();
    selectRegion('sagaing');
    initContactFormValidation();
}

document.addEventListener('DOMContentLoaded', initPage);
